-- Story 25.1: the Family identity tables. All three are read before a tenant exists, so they are
-- listed in backend/GLOBAL_TABLES.md and are not mapped with @TenantId. Primary keys are UUIDv7
-- generated by the application (no database default).

CREATE TABLE families (
    id         uuid PRIMARY KEY,
    timezone   text        NOT NULL,
    week_start text        NOT NULL DEFAULT 'MONDAY'
        CHECK (week_start IN ('MONDAY', 'TUESDAY', 'WEDNESDAY', 'THURSDAY', 'FRIDAY', 'SATURDAY', 'SUNDAY')),
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE caregivers (
    id           uuid PRIMARY KEY,
    sub          text        NOT NULL UNIQUE,
    display_name text        NOT NULL,
    email        text        NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE caregiver_membership (
    id           uuid PRIMARY KEY,
    caregiver_id uuid        NOT NULL REFERENCES caregivers ON DELETE CASCADE,
    family_id    uuid        NOT NULL REFERENCES families ON DELETE CASCADE,
    role         text        NOT NULL DEFAULT 'caregiver' CHECK (role = 'caregiver'),
    joined_at    timestamptz NOT NULL DEFAULT now(),
    ended_at     timestamptz,
    end_reason   text,
    CHECK (ended_at IS NOT NULL OR end_reason IS NULL)
);

-- A Caregiver belongs to at most one active Family (AD-3).
CREATE UNIQUE INDEX caregiver_membership_one_active ON caregiver_membership (caregiver_id) WHERE ended_at IS NULL;
CREATE INDEX caregiver_membership_family ON caregiver_membership (family_id);
